const transcript = $('init_variables').first().json.transcript

// Initialize counters for bot (AI) and user words
let bot_word_count = 0;
let user_word_count = 0;

// Split the transcript into lines based on the newline character '\n'
// Each line represents either the AI or the User speaking
const lines = transcript.split('\n');

// Loop through each line in the transcript
for (let i = 0; i < lines.length; i++) {
    // Check if the line starts with "AI:" or "User:"
    if (lines[i].startsWith('AI:')) {
        // Remove "AI:" prefix and split the remaining text into words
        const words = lines[i].replace('AI:', '').trim().split(/\s+/);
        // Add the number of words to the bot's word count
        bot_word_count += words.length;
    } else if (lines[i].startsWith('User:')) {
        // Remove "User:" prefix and split the remaining text into words
        const words = lines[i].replace('User:', '').trim().split(/\s+/);
        // Add the number of words to the user's word count
        user_word_count += words.length;
    }
}

// Calculate the total word count (AI + User)
const total_word_count = bot_word_count + user_word_count;

// Avoid dividing by zero to prevent errors in case there's no data
let bot_word_percent = 0;
let user_word_percent = 0;

if (total_word_count > 0) {
    // Calculate the word percentages for AI and User
    bot_word_percent = Math.round((bot_word_count / total_word_count) * 100);
    user_word_percent = Math.round((user_word_count / total_word_count) * 100);
}

// Output the results for use in other parts of the workflow
return {
    bot_word_count: bot_word_count,
    bot_word_percent: bot_word_percent + '%',
    user_word_count: user_word_count,
    user_word_percent: user_word_percent + '%'
};

